// src/content/oss.ts
// Typed access to the upstream contribution snapshot in oss-data.json.
//
// The JSON is generated by scripts/fetch-oss.mjs and committed. Nothing here
// invents or rounds anything: every row came from GitHub, and `fetchedAt` says
// when.

import raw from "./oss-data.json";
import prsRaw from "./oss-prs.json";

export type PrState = "merged" | "open" | "closed";

export type OssPr = {
  number: number;
  title: string;
  url: string;
  state: PrState;
  created: string;
  closedAt: string | null;
  mergedAt?: string | null;
  mergedBy?: string;
  additions?: number;
  deletions?: number;
  closeReason?: string;
  closeEvidence?: string;
  closedBy?: string;
};

export type OssRepo = {
  full: string;
  owner: string;
  name: string;
  slug: string;
  org?: string;
  stars?: number;
  reach?: string;
  level?: string;
  merged: number;
  open: number;
  closed: number;
  prs: OssPr[];
};

export type OssOrg = {
  org: string;
  slug: string;
  avatar?: string;
  kind?: string;
  merged: number;
  open: number;
  closed: number;
  carried?: number;
  reportsFixed?: number;
  contributions: number;
  level?: string;
  repos: string[];
};

export type OssCarried = { repo: string; org: string; pr: number; commit: string; title: string; url: string };

export type OssReportFixed = {
  repo: string;
  org: string;
  number: number;
  title: string;
  url: string;
  fixedBy: string;
  fixUrl: string;
  how: string;
};

export type OssData = {
  schema: number;
  user: string;
  fetchedAt: string;
  definition?: string;
  totals: {
    contributions: number;
    merged: number;
    open: number;
    carried?: number;
    reportsFixed?: number;
    closed: number;
    prs: number;
    orgs: number;
    orgsLanded: number;
    repos: number;
    reposLanded: number;
  };
  orgs: OssOrg[];
  repos: OssRepo[];
  carried?: OssCarried[];
  reportsFixed?: OssReportFixed[];
  closedReasons?: { key: string; label: string; count: number }[];
};

export const oss = raw as unknown as OssData;

/** Why a pull request closed without merging. Labels say what GitHub shows and nothing more. */
export const CLOSE_REASONS: Record<string, { label: string; desc: string }> = {
  landed: { label: "Landed another way", desc: "A maintainer applied the change themselves." },
  superseded: { label: "Replaced by another PR", desc: "A different pull request took over the work." },
  resubmitted: { label: "Resubmitted by me", desc: "I closed it and continued in a new pull request." },
  auto: { label: "Closed automatically", desc: "A stale bot, CLA bot or similar closed it." },
  mine: { label: "Closed by me", desc: "I withdrew it or moved the work elsewhere." },
  declined: { label: "Closed by a maintainer", desc: "Closed without merging, with no further signal in the GitHub data." },
  unknown: { label: "Reason not recorded", desc: "The data does not say why it closed." },
};

export const CLOSE_REASON_ORDER = ["landed", "superseded", "resubmitted", "auto", "mine", "declined", "unknown"];

export function closeReasonOf(pr: OssPr): string {
  return pr.closeReason && pr.closeReason in CLOSE_REASONS ? pr.closeReason : "unknown";
}

export type ClosedGroup = { key: string; label: string; desc: string; prs: OssPr[] };

/** Closed pull requests grouped by reason, in a fixed order, empty groups left out. */
export function groupClosed(prs: OssPr[]): ClosedGroup[] {
  const closed = prs.filter((p) => p.state === "closed");
  return CLOSE_REASON_ORDER.map((key) => ({
    key,
    ...CLOSE_REASONS[key],
    prs: closed.filter((p) => closeReasonOf(p) === key),
  })).filter((g) => g.prs.length > 0);
}

const when = (p: OssPr) => p.mergedAt ?? p.closedAt ?? p.created;
const newestFirst = (a: OssPr, b: OssPr) => (when(b) > when(a) ? 1 : -1);

export const mergedPrs = (prs: OssPr[]) => prs.filter((p) => p.state === "merged").sort(newestFirst);
export const openPrs = (prs: OssPr[]) => prs.filter((p) => p.state === "open").sort(newestFirst);
export const closedPrs = (prs: OssPr[]) => prs.filter((p) => p.state === "closed").sort(newestFirst);

const lc = (s: string | undefined) => (s ?? "").toLowerCase();

/** All repos sorted by landed merges first, then open PRs, then total PRs. */
export const allRepos: OssRepo[] = [...oss.repos].sort((a, b) => {
  if (b.merged !== a.merged) return b.merged - a.merged;
  if (b.open !== a.open) return b.open - a.open;
  return b.prs.length - a.prs.length;
});

/** Repos with at least one merged PR, best first. These are the record. */
export const mergedRepos: OssRepo[] = allRepos.filter((r) => r.merged > 0);

/** Everything else: open or closed, nothing landed yet. */
export const pendingRepos: OssRepo[] = oss.repos.filter((r) => r.merged === 0);

export function getRepo(slug: string): OssRepo | undefined {
  return oss.repos.find((r) => r.slug === slug);
}

export function repoSlugs(): string[] {
  return oss.repos.map((r) => r.slug);
}

/** Organisations by contributions, then open pull requests, then name. */
export const allOrgs: OssOrg[] = [...oss.orgs].sort(
  (a, b) => b.contributions - a.contributions || b.open - a.open || a.org.localeCompare(b.org)
);

export function getOrg(slug: string): OssOrg | undefined {
  return oss.orgs.find((o) => o.slug === slug);
}

export function orgSlugs(): string[] {
  return oss.orgs.map((o) => o.slug);
}

/** The organisation a repo belongs to, matched case-insensitively on its org, then its owner. */
export function orgOfRepo(r: OssRepo): OssOrg | undefined {
  return oss.orgs.find((o) => lc(o.org) === lc(r.org ?? r.owner)) ?? oss.orgs.find((o) => lc(o.org) === lc(r.owner));
}

export function reposOfOrg(o: OssOrg): OssRepo[] {
  return allRepos.filter((r) => lc(r.org ?? r.owner) === lc(o.org) || lc(r.owner) === lc(o.org));
}

export function carriedOfOrg(o: OssOrg): OssCarried[] {
  return (oss.carried ?? []).filter((c) => lc(c.org) === lc(o.org));
}

export function reportsFixedOfOrg(o: OssOrg): OssReportFixed[] {
  return (oss.reportsFixed ?? []).filter((c) => lc(c.org) === lc(o.org));
}

/** What the client list needs for one organisation, with closed pull requests already left out. */
export type OrgRow = {
  slug: string;
  org: string;
  contributions: number;
  merged: number;
  open: number;
  level: string;
  repos: {
    full: string;
    name: string;
    slug: string;
    merged: number;
    open: number;
    prs: { number: number; title: string; url: string; state: PrState; created: string }[];
  }[];
};

export function orgRows(): OrgRow[] {
  return allOrgs.map((o) => ({
    slug: o.slug,
    org: o.org,
    contributions: o.contributions,
    merged: o.merged,
    open: o.open,
    level: o.level ?? "",
    repos: reposOfOrg(o)
      .filter((r) => r.merged + r.open > 0)
      .map((r) => ({
        full: r.full,
        name: r.name,
        slug: r.slug,
        merged: r.merged,
        open: r.open,
        prs: [...mergedPrs(r.prs), ...openPrs(r.prs)].map((p) => ({
          number: p.number,
          title: p.title,
          url: p.url,
          state: p.state,
          created: p.created,
        })),
      })),
  }));
}

